package messaging

import (
	"context"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"

	"github.com/google/uuid"
	"github.com/jackc/pgx/v5"

	"github.com/furkanmeclis/messora-app-go/internal/db"
	"github.com/furkanmeclis/messora-app-go/internal/modules/whatsapp"
)

// MediaStore keeps media files on a local volume. Keys are relative paths
// generated by Messora only, so they can never escape the root.
type MediaStore struct{ root string }

// NewMediaStore returns a store rooted at dir.
func NewMediaStore(dir string) *MediaStore { return &MediaStore{root: dir} }

// Create opens a temporary file; Commit moves it under its final key.
func (m *MediaStore) Create() (*os.File, error) {
	if err := os.MkdirAll(filepath.Join(m.root, "tmp"), 0o750); err != nil {
		return nil, err
	}
	return os.CreateTemp(filepath.Join(m.root, "tmp"), "dl-*")
}

// Commit moves a finished temp file to key.
func (m *MediaStore) Commit(tmp, key string) error {
	dst := filepath.Join(m.root, filepath.FromSlash(key))
	if err := os.MkdirAll(filepath.Dir(dst), 0o750); err != nil {
		return err
	}
	return os.Rename(tmp, dst)
}

// Open returns a stored file.
func (m *MediaStore) Open(key string) (*os.File, error) {
	if key == "" || strings.Contains(key, "..") || filepath.IsAbs(key) {
		return nil, errors.New("media: invalid key")
	}
	return os.Open(filepath.Join(m.root, filepath.FromSlash(key))) //nolint:gosec // key is generated by Messora and checked above
}

func mediaKey(id uuid.UUID) string {
	s := id.String()
	var b [4]byte
	_, _ = rand.Read(b[:])
	return fmt.Sprintf("%s/%s/%s-%s", s[:2], s[2:4], s, hex.EncodeToString(b[:]))
}

// DownloadMedia fetches inbound media from Meta onto the media volume.
// Permanent problems mark the file failed; transient ones are returned so
// the task is retried.
func (s *Service) DownloadMedia(ctx context.Context, id uuid.UUID) error {
	f, err := s.q.GetMediaFile(ctx, id)
	if errors.Is(err, pgx.ErrNoRows) || (err == nil && f.Status == "stored") {
		return nil
	}
	if err != nil {
		return err
	}
	if f.MessageID == nil || f.MetaMediaID == nil {
		return s.q.MarkMediaFailed(ctx, db.MarkMediaFailedParams{ID: id, LastError: ptr("no Meta media id")})
	}
	msg, err := s.q.GetMessage(ctx, *f.MessageID)
	if err != nil {
		return err
	}
	sender, err := s.ch.SenderFor(ctx, msg.PhoneNumberID)
	if err != nil {
		return s.q.MarkMediaFailed(ctx, db.MarkMediaFailedParams{ID: id, LastError: ptr(err.Error())})
	}
	client := s.ch.Client()
	info, err := client.GetMedia(ctx, *f.MetaMediaID, sender.Token)
	if err != nil {
		var api *whatsapp.APIError
		if errors.As(err, &api) && api.HTTPStatus < 500 && api.HTTPStatus != 429 {
			return s.q.MarkMediaFailed(ctx, db.MarkMediaFailedParams{ID: id, LastError: ptr(truncate(api.Error(), 500))})
		}
		return err
	}
	tmp, err := s.media.Create()
	if err != nil {
		return err
	}
	defer func() { _ = os.Remove(tmp.Name()) }() // no-op after a successful rename
	h := sha256.New()
	n, err := client.DownloadMedia(ctx, info.URL, sender.Token, io.MultiWriter(tmp, h), s.maxMedia)
	cerr := tmp.Close()
	if err != nil {
		if n > s.maxMedia {
			return s.q.MarkMediaFailed(ctx, db.MarkMediaFailedParams{ID: id, LastError: ptr("file exceeds the size limit")})
		}
		return err
	}
	if cerr != nil {
		return cerr
	}
	// Meta documents sha256 as hex; compare when both sides have one.
	if want := strings.ToLower(f.Sha256); want != "" && len(want) == 64 && want != hex.EncodeToString(h.Sum(nil)) {
		return s.q.MarkMediaFailed(ctx, db.MarkMediaFailedParams{ID: id, LastError: ptr("checksum mismatch")})
	}
	key := mediaKey(id)
	if err := s.media.Commit(tmp.Name(), key); err != nil {
		return err
	}
	return s.q.MarkMediaStored(ctx, db.MarkMediaStoredParams{ID: id, StorageKey: &key, SizeBytes: &n})
}
